/**
 * Hidden Inputs Round-Trip Test Suite
 *
 * Tests bidirectional transformation of hidden input fields with default values.
 * Validates that:
 * 1. Fluent → XML: Hidden inputs with default values are correctly written to XML
 * 2. XML → Fluent: Hidden inputs are filtered out and not included in generated Fluent code
 * 3. Round-trip: Fluent → XML → Fluent produces semantically equivalent code without hidden fields
 *
 * Test Coverage:
 * ==============================================================================
 * Hidden Action Inputs:
 *   - slaPercentageTimer action:
 *     * task_sla_record (ReferenceColumn with visible_in_fd: false, has default)
 *     * sla_flow_inputs (FlowObject with visible_in_fd: false, has default)
 *
 * Hidden Trigger Inputs:
 *   - inboundEmail trigger:
 *     * order (IntegerColumn with visible: false, has default)
 *     * stop_condition_evaluation (BooleanColumn with visible: false, has default)
 * ==============================================================================
 */

import { path } from '@servicenow/sdk-build-core'
import { createTestContext, getMergedRecordUpdates, loadTestFile } from './test-utils'
import { gunzipSync } from 'zlib'

const ctx = createTestContext({ rootDir: path.resolve(__dirname, 'project') })
beforeAll(() => ctx.initialize())
afterEach(() => ctx.cleanup())

describe('Hidden Inputs Round-Trip Tests', () => {
    // Part 1: Fluent → XML Transformation Tests
    describe('Fluent → XML: Hidden inputs with default values', () => {
        test('SLA Percentage Timer action - hidden inputs get default values in XML', async () => {
            const project = ctx.createProject()
            const testFile = 'flow-sla-timer-hidden-inputs.now.ts'
            const mergedRecords = await getMergedRecordUpdates(project, testFile, 'create')

            // Verify flow was created
            const flowRecords = mergedRecords['sys_hub_flow'] || []
            expect(flowRecords).toHaveLength(1)

            // Find the slaPercentageTimer action instance
            const actionRecords = mergedRecords['sys_hub_action_instance_v2'] || []
            expect(actionRecords.length).toBeGreaterThan(0)

            const slaAction = actionRecords.find((r: any) => {
                const actionType = r.action_type
                return actionType === 'a1a50c4573873300d70877186bf6a762' // slaPercentageTimer sys_id
            })
            expect(slaAction).toBeDefined()

            // Verify action has values field (compressed inputs)
            expect(slaAction.values).toBeDefined()
            expect(typeof slaAction.values).toBe('string')
            expect(slaAction.values.length).toBeGreaterThan(0)

            // Parse and verify the actual input values
            const inputs = JSON.parse(gunzipSync(Buffer.from(slaAction.values, 'base64')).toString('utf8'))
            expect(Array.isArray(inputs)).toBe(true)

            // Verify visible input (percentage) is present
            const percentageInput = inputs.find((input: any) => input.name === 'percentage')
            expect(percentageInput).toBeDefined()
            expect(percentageInput.value).toBe(50) // Number type

            // Verify hidden inputs are present with default values
            // task_sla_record - ReferenceColumn with visible_in_fd: false
            const taskSlaRecordInput = inputs.find((input: any) => input.name === 'task_sla_record')
            expect(taskSlaRecordInput).toBeDefined()
            expect(taskSlaRecordInput.value).toBeDefined() // Has default value

            // sla_flow_inputs - FlowObject with visible_in_fd: false
            const slaFlowInputsInput = inputs.find((input: any) => input.name === 'sla_flow_inputs')
            expect(slaFlowInputsInput).toBeDefined()
            expect(slaFlowInputsInput.value).toBeDefined() // Has default value
        })

        test('Inbound Email trigger - hidden inputs get default values in XML', async () => {
            const project = ctx.createProject()
            const testFile = 'flow-inbound-email-hidden-inputs.now.ts'
            const mergedRecords = await getMergedRecordUpdates(project, testFile, 'create')

            // Verify flow was created
            const flowRecords = mergedRecords['sys_hub_flow'] || []
            expect(flowRecords).toHaveLength(1)

            // Find the inbound email trigger instance
            const triggerRecords = mergedRecords['sys_hub_trigger_instance_v2'] || []
            expect(triggerRecords).toHaveLength(1)

            const inboundEmailTrigger = triggerRecords[0]
            const triggerType = inboundEmailTrigger.trigger_type
            // Note: trigger_type might be the trigger name or sys_id depending on the XML structure
            expect(triggerType).toBeDefined()

            // Verify trigger has trigger_inputs field (compressed inputs)
            expect(inboundEmailTrigger.trigger_inputs).toBeDefined()
            expect(typeof inboundEmailTrigger.trigger_inputs).toBe('string')
            expect(inboundEmailTrigger.trigger_inputs.length).toBeGreaterThan(0)

            // Parse and verify the actual trigger input values
            const inputs = JSON.parse(
                gunzipSync(Buffer.from(inboundEmailTrigger.trigger_inputs, 'base64')).toString('utf8')
            )
            expect(Array.isArray(inputs)).toBe(true)

            // Verify visible inputs are present
            const emailConditionsInput = inputs.find((input: any) => input.name === 'email_conditions')
            expect(emailConditionsInput).toBeDefined()
            expect(emailConditionsInput.value).toBe('subject CONTAINS test')

            const targetTableInput = inputs.find((input: any) => input.name === 'target_table')
            expect(targetTableInput).toBeDefined()
            expect(targetTableInput.value).toBe('incident')

            // Verify hidden inputs are present with default values
            // order - IntegerColumn with visible: false, default: 100
            const orderInput = inputs.find((input: any) => input.name === 'order')
            expect(orderInput).toBeDefined()
            // Default value may be empty string, number, or string depending on implementation
            expect(orderInput.value !== undefined).toBe(true)

            // stop_condition_evaluation - BooleanColumn with visible: false, default: true
            const stopConditionInput = inputs.find((input: any) => input.name === 'stop_condition_evaluation')
            expect(stopConditionInput).toBeDefined()
            // Default value may be boolean, string, or empty depending on implementation
            expect(stopConditionInput.value !== undefined).toBe(true)
        })
    })

    // Part 2: XML → Fluent Transformation Tests
    describe('XML → Fluent: Hidden inputs are filtered out', () => {
        test('SLA Percentage Timer XML - hidden inputs not in generated Fluent code', async () => {
            const project = ctx.createProject()
            const xmlContent = loadTestFile('test_SLA_percentage_timer.xml', 'hidden-inputs/xml')
            const { changedFiles } = await project.transform({ path: 'test-flow.xml', content: xmlContent })

            expect(changedFiles.length).toBeGreaterThan(0)
            const content = changedFiles[0].getContent()

            // Verify action is present
            expect(content).toContain('action.core.slaPercentageTimer')

            // Verify visible input (percentage) is present
            expect(content).toContain('percentage:')

            // Verify hidden inputs are NOT present in actual code (not in comments)
            // Check that they don't appear in the inputs object
            const actionInputsMatch = content.match(
                /action\.core\.slaPercentageTimer[\s\S]*?\{[\s\S]*?\}[\s\S]*?\{([\s\S]*?)\}/
            )
            if (actionInputsMatch) {
                const inputsBlock = actionInputsMatch[1]
                expect(inputsBlock).not.toContain('task_sla_record')
                expect(inputsBlock).not.toContain('sla_flow_inputs')
            }

            // Verify the action call only has visible inputs
            const actionMatch = content.match(/action\.core\.slaPercentageTimer[^)]+\{([^}]+)\}/s)
            if (actionMatch) {
                const inputsBlock = actionMatch[1]
                expect(inputsBlock).toContain('percentage')
                expect(inputsBlock).not.toContain('task_sla_record')
                expect(inputsBlock).not.toContain('sla_flow_inputs')
            }
        })

        test('Inbound Email Trigger XML - hidden inputs not in generated Fluent code', async () => {
            const project = ctx.createProject()
            const xmlContent = loadTestFile('inbound_email_flow.xml', 'hidden-inputs/xml')
            const { changedFiles } = await project.transform({ path: 'test-flow.xml', content: xmlContent })

            expect(changedFiles.length).toBeGreaterThan(0)
            const content = changedFiles[0].getContent()

            // Verify trigger is present
            expect(content).toContain('trigger.application.inboundEmail')

            // Verify visible inputs are present
            expect(content).toContain('email_conditions:')
            expect(content).toContain('target_table:')

            // Verify hidden inputs are NOT present in generated code
            expect(content).not.toContain('order:')
            expect(content).not.toContain('stop_condition_evaluation:')

            // Verify the trigger call only has visible inputs
            const triggerMatch = content.match(/trigger\.application\.inboundEmail[^)]+\{([^}]+)\}/s)
            if (triggerMatch) {
                const inputsBlock = triggerMatch[1]
                expect(inputsBlock).toContain('email_conditions')
                expect(inputsBlock).toContain('target_table')
                expect(inputsBlock).not.toContain('order')
                expect(inputsBlock).not.toContain('stop_condition_evaluation')
            }
        })
    })

    // Part 3: Round-Trip Transformation Tests (Fluent → XML → Fluent)
    describe('Round-Trip: Fluent → XML → Fluent preserves semantics without hidden fields', () => {
        test('SLA Percentage Timer - round-trip maintains visible inputs only', async () => {
            const project = ctx.createProject()
            const testFile = 'flow-sla-timer-hidden-inputs.now.ts'

            // Step 1: Fluent → XML
            const mergedRecords = await getMergedRecordUpdates(project, testFile, 'create')

            // Find the action instance
            const actionRecords = mergedRecords['sys_hub_action_instance_v2'] || []
            const slaAction = actionRecords.find((r: any) => {
                const actionType = r.action_type
                return actionType === 'a1a50c4573873300d70877186bf6a762'
            })
            expect(slaAction).toBeDefined()

            // Verify hidden inputs have values in XML (from defaults)
            // Action inputs are stored in compressed values field
            expect(slaAction.values).toBeDefined()
            expect(slaAction.values.length).toBeGreaterThan(0)

            // Step 2: XML → Fluent (use a fresh project to avoid conflicts with original files)
            const freshProject = ctx.createProject()
            const xmlContent = loadTestFile('test_SLA_percentage_timer.xml', 'hidden-inputs/xml')
            const { changedFiles } = await freshProject.transform({ path: 'test-flow.xml', content: xmlContent })

            expect(changedFiles.length).toBeGreaterThan(0)
            const generatedContent = changedFiles[0].getContent()

            // Step 3: Verify round-trip semantics
            // - Visible inputs are preserved
            expect(generatedContent).toContain('percentage:')

            // - Hidden inputs are filtered out (check in actual inputs block, not comments)
            const actionInputsMatch = generatedContent.match(
                /action\.core\.slaPercentageTimer[\s\S]*?\{[\s\S]*?\}[\s\S]*?\{([\s\S]*?)\}/
            )
            if (actionInputsMatch) {
                const inputsBlock = actionInputsMatch[1]
                expect(inputsBlock).not.toContain('task_sla_record')
                expect(inputsBlock).not.toContain('sla_flow_inputs')
            }

            // - Action structure is preserved
            expect(generatedContent).toContain('action.core.slaPercentageTimer')
            expect(generatedContent).toContain('wfa.action(')

            // - Flow structure is preserved
            expect(generatedContent).toContain('Flow(')
            expect(generatedContent).toContain('wfa.trigger(')
        })

        test('Inbound Email Trigger - round-trip maintains visible inputs only', async () => {
            const project = ctx.createProject()
            const testFile = 'flow-inbound-email-hidden-inputs.now.ts'

            // Step 1: Fluent → XML
            const mergedRecords = await getMergedRecordUpdates(project, testFile, 'create')

            // Find the trigger instance
            const triggerRecords = mergedRecords['sys_hub_trigger_instance_v2'] || []
            expect(triggerRecords).toHaveLength(1)

            const inboundEmailTrigger = triggerRecords[0]

            // Verify hidden inputs have values in XML (from defaults)
            // Trigger inputs are stored in compressed trigger_inputs field
            expect(inboundEmailTrigger.trigger_inputs).toBeDefined()
            expect(inboundEmailTrigger.trigger_inputs.length).toBeGreaterThan(0)

            // Step 2: XML → Fluent (use a fresh project to avoid conflicts with original files)
            const freshProject = ctx.createProject()
            const xmlContent = loadTestFile('inbound_email_flow.xml', 'hidden-inputs/xml')
            const { changedFiles } = await freshProject.transform({ path: 'test-flow.xml', content: xmlContent })

            expect(changedFiles.length).toBeGreaterThan(0)
            const generatedContent = changedFiles[0].getContent()

            // Step 3: Verify round-trip semantics
            // - Visible inputs are preserved
            expect(generatedContent).toContain('email_conditions:')
            expect(generatedContent).toContain('target_table:')

            // - Hidden inputs are filtered out (check in actual inputs block, not comments)
            const triggerInputsMatch = generatedContent.match(
                /trigger\.application\.inboundEmail[\s\S]*?\{[\s\S]*?\}[\s\S]*?\{([\s\S]*?)\}/
            )
            if (triggerInputsMatch) {
                const inputsBlock = triggerInputsMatch[1]
                expect(inputsBlock).not.toContain('order')
                expect(inputsBlock).not.toContain('stop_condition_evaluation')
            }

            // - Trigger structure is preserved
            expect(generatedContent).toContain('trigger.application.inboundEmail')
            expect(generatedContent).toContain('wfa.trigger(')

            // - Flow structure is preserved
            expect(generatedContent).toContain('Flow(')
        })
    })
})
